function resourceOptions(kind,selected=[],multi=false){const list=kind==='role'?state.resources.roles.filter(x=>!x.managed):kind==='member'?state.resources.members:kind==='category'?state.resources.channels.filter(x=>Number(x.type)===4):state.resources.channels.filter(x=>[0,2,5,13].includes(Number(x.type))); const ids=new Set((Array.isArray(selected)?selected:[selected]).filter(Boolean).map(String)); return list.map(x=>`<option value="${esc(x.id)}" ${ids.has(String(x.id))?'selected':''}>${esc(kind==='channel'?'# '+x.name:(kind==='role'?'@ '+x.name:x.name))}</option>`).join('');}
function select(id,kind,value,multi=false,label='',required=false){return `<label class="field"><span>${label}</span><select id="${id}" ${multi?'multiple':''} ${required?'required':''}>${multi?'':`<option value="">— غير محدد —</option>`}${resourceOptions(kind,value,multi)}</select></label>`}
function val(id){return $(id)?.value||''} function vals(id){return [...($(id)?.selectedOptions||[])].map(o=>o.value)}
function toggle(id,checked,label){return `<label class="toggle-row"><span>${label}</span><input id="${id}" type="checkbox" ${checked?'checked':''}><i></i></label>`}
function input(id,label,value='',type='text',extra=''){return `<label class="field"><span>${label}</span><input id="${id}" type="${type}" value="${esc(value??'')}" ${extra}></label>`}
function textarea(id,label,value=''){return `<label class="field full"><span>${label}</span><textarea id="${id}" rows="5">${esc(value??'')}</textarea></label>`}
function button(label,id='save',cls='primary'){return `<button class="btn ${cls}" data-action="${id}">${label}</button>`}
function card(icon,title,desc,body=''){return `<article class="card"><header class="card-head"><div class="system-icon">${icon}</div><div><h3>${title}</h3><p>${desc}</p></div></header>${body}</article>`}
function sectionHead(kicker,title,desc){const sid=state.section;return `<div class="hero"><div><span>${kicker}</span><h1>${title}</h1><p>${desc}</p></div><div class="hero-actions">${button('صلاحيات القائمة','open-permissions:'+sid,'ghost')}<div class="hero-orb">✦</div></div></div>`}
async function boot(){
  renderNav();
  state.user=await api('/api/user'); const gd=await api('/api/guilds'); state.guilds=gd?.guilds||[];
  fillGuilds();
  const id=localStorage.getItem('revo_guild'); if(id && state.guilds.some(g=>g.id===id)) await selectGuild(id); else if(state.guilds[0]) await selectGuild(state.guilds[0].id); else render();
  const info=await api('/api/bot/info'); if(info){$('#botStatus').textContent=info.online?'Online • Revo Bot':'Offline';$('#ownerName').textContent=info.owner?.globalName||info.owner?.username||'—';$('#ownerTag').textContent=info.owner?.mention||'—';if(info.owner?.avatar)$('#ownerAvatar').src=info.owner.avatar; if(info.bot?.avatar) document.title=`${info.bot.globalName} • Control Center`;}
  if(state.user?.avatar)$('#meAvatar').src=state.user.avatar;
}
function renderNav(){ $('#nav').innerHTML=NAV.map(([id,ic,t])=>`<button data-nav="${id}" class="nav-btn">${ic}<span>${t}</span></button>`).join(''); $$('#nav button').forEach(b=>b.onclick=()=>setSection(b.dataset.nav)); $('#menu').onclick=()=>{ $('.sidebar').classList.add('open'); $('#sidebarOverlay')?.classList.add('show'); }; $('#sideClose')?.addEventListener('click',closeSide); $('#sidebarOverlay')?.addEventListener('click',closeSide); }
function fillGuilds(){ $('#guildSelect').innerHTML='<option value="">اختر سيرفر...</option>'+state.guilds.map(g=>`<option value="${g.id}">${esc(g.name)}</option>`).join(''); $('#guildSelect').value=state.guild?.id||''; $('#guildSelect').onchange=()=>selectGuild($('#guildSelect').value); }
async function selectGuild(id){ if(!id)return; localStorage.setItem('revo_guild',id); state.guild=state.guilds.find(g=>g.id===id)||{id}; $('#guildSelect').value=id; $('#guildTitle').textContent=state.guild.name||id; [state.resources,state.config,state.catalog,state.advanced,state.economy,state.moderation,state.utilityData,state.premiumData]=await Promise.all([api(gurl('/api/guild/resources')),api(gurl('/api/guild/full-config')),api('/api/bot/catalog'),api(gurl('/api/guild/advanced')),api(gurl('/api/guild/economy')),api(gurl('/api/guild/moderation')),api(gurl('/api/guild/utility')),api(gurl('/api/guild/premium'))]); const gs=await api(gurl('/api/guild/stats')); if(gs) state.guild={...state.guild,...gs}; render(); }
function setSection(id){state.section=id;document.querySelectorAll('.nav-btn').forEach(b=>b.classList.toggle('active',b.dataset.nav===id));render();closeSide();}
function render(){const title=NAV.find(x=>x[0]===state.section);$('#sectionTitle').textContent=title?.[2]||'Revo';const pages={overview:overview,economy:economy,moderation:moderation,protection:protection,welcome:welcome,autoresponse:autoresponse,tickets:tickets,levels:levels,functions:functions,logs:logs,slash:slash,publisher:publisher,rooms:rooms,premium:premium,utility:utility,commands:commands,core:core,advanced:advanced};$('#app').innerHTML=state.guild?pages[state.section]():`<div class="empty"><h2>اختار سيرفر</h2><p>اختر سيرفر من القائمة بالأعلى.</p></div>`;bind();}
function overview(){const c=state.config||{};const enabled=Object.values(c.protection?.protection||{}).filter(x=>x?.enabled).length;return sectionHead('REVO / CONTROL CENTER','مركز التحكم الكامل',`كل إعدادات البوت في مكان واحد — ${state.guild?.name||''}`)+`<div class="stats"><div><b>${fmt(state.guild?.memberCount||0)}</b><span>أعضاء يمكن إدارتهم</span></div><div><b>${Object.keys(c.protection?.protection||{}).length||17}</b><span>أنظمة حماية</span></div><div><b>${c.tickets?.length||0}</b><span>Ticket Panels</span></div><div><b>${enabled}</b><span>حمايات مفعلة</span></div></div><div class="grid two">${card('✦','اختصارات الإدارة','كل shortcut محفوظ في البوت',`<p class="muted">${c.system?.shortcuts?.length||0} اختصار</p>${button('إدارة الاختصارات','shortcuts')}`)}${card('◈','أنظمة Revo','النسخة الحقيقية من أنظمة البوت',`<div class="chips">${(state.catalog?.systems||[]).map(s=>`<span>${s.icon} ${esc(s.name)}</span>`).join('')}</div>`)}${card('♔','هوية صاحب البوت','مالك المشروع يظهر تلقائيًا من Discord',`<div class="owner-preview"><img src="${esc($('#ownerAvatar')?.src||'')}"/><div><b>${esc($('#ownerName')?.textContent||'—')}</b><small>${esc($('#ownerTag')?.textContent||'—')}</small></div></div>`)}${card('✧','حالة الداتا','MongoDB + Discord API',`<p class="muted">كل القوائم تعتمد على البيانات الحقيقية، والـRoles/Channels تُسحب مباشرة من السيرفر.</p>`)}</div>`}
function economy(){const e=state.economy||{};const a=e.account||{};const top=e.top||[];const tx=e.transfers||[];const fb=e.feedback||[];const txRows=tx.slice(0,20).map(x=>{const incoming=x.type==='incoming';const other=incoming?x.from:x.to;return `<div class="transfer-item ${incoming?'in':'out'}"><div class="transfer-avatar">${esc((incoming?x.fromInitials:x.toInitials)||'RV')}</div><div class="transfer-main"><b>${incoming?'تحويل وارد':'تحويل صادر'}</b><span>${esc(other||'Revo System')}</span><small>${esc(x.reason||'تحويل Revo')} • ${esc(x.timeAgo||'')}</small></div><div class="transfer-meta"><strong>${incoming?'+':'−'}${fmt(Math.abs(x.amount||0))}</strong><small>${x.tax?`ضريبة ${fmt(x.tax)}`:''}</small></div></div>`}).join('')||'<div class="empty compact">لا توجد عمليات تحويل لهذا الحساب حتى الآن.</div>';return sectionHead('ECONOMY / REVO','الاقتصاد والحسابات','حسابك الحقيقي، اليومية، التحويلات، الـVIP، الـFeedback والمتصدرين.')+`<div class="stats"><div><b>${fmt(a.balance||0)}</b><span>رصيدك</span></div><div><b>${fmt(e.stats?.count||0)}</b><span>عمليات السيرفر</span></div><div><b>${fmt(e.stats?.volume||0)}</b><span>حجم التحويلات</span></div><div><b>${fb.length}</b><span>Feedback</span></div></div><div class="grid two">${card('◆','Daily Reward','المكافأة اليومية الفعلية من نظام Revo',`<div class="metric-row"><b>${fmt(e.daily?.reward||5000)}</b><span>Revo / 24h</span></div><div class="metric-row"><b>${a.nextDailyRewardAt?new Date(a.nextDailyRewardAt).toLocaleString('ar-EG'):'متاحة الآن'}</b><span>الحالة</span></div>${button('استلام اليومية','claim-daily','primary')}`)}${card('◆','VIP Reward','المكافأة الدورية وحالة VIP',`<div class="metric-row"><b>${a.isVip?'VIP':'عادي'}</b><span>الحالة</span></div><div class="metric-row"><b>${a.nextVipRewardAt?new Date(a.nextVipRewardAt).toLocaleString('ar-EG'):'—'}</b><span>الموعد القادم</span></div>`)}${card('♛','Leaderboard','أعلى الحسابات الاقتصادية',`<div class="list">${top.slice(0,10).map((x,i)=>`<div class="list-row"><b>#${i+1}</b><span>${esc(x.userId)}</span><strong>${fmt(x.balance||0)}</strong></div>`).join('')||'<span class="muted">لا توجد بيانات.</span>'}</div>`)}</div><div class="grid two"><section class="form-card transfer-history"><div class="section-inline"><div><span class="eyebrow">TRANSFER LEDGER</span><h3>سجل التحويلات</h3><p class="hint">آخر تحويلات حسابك الفعلية من قاعدة بيانات Revo.</p></div><span class="live-chip">LIVE DATA</span></div><div class="transfer-list">${txRows}</div></section>${card('✎','Feedback','حالات Feedback والمكافآت',`<div class="chips"><span>Pending: ${fb.filter(x=>x.status==='pending').length}</span><span>Rewarded: ${fb.filter(x=>x.status==='rewarded').length}</span><span>Rejected: ${fb.filter(x=>x.status==='rejected').length}</span></div>`)}</div>`}
function moderation(){const cmds=(state.catalog?.commands||[]).filter(x=>['Administration','Moderation','Voice'].includes(x.category));const m=state.moderation||{};return sectionHead('MODERATION / ADMIN','الإدارة والعقوبات','كل أوامر الإدارة الفعلية + الاختصارات + التحذيرات + السجلات في مكان واحد.')+`<div class="stats"><div><b>${m.warnings?.length||0}</b><span>تحذيرات محفوظة</span></div><div><b>${m.shortcuts?.length||0}</b><span>Shortcuts</span></div><div><b>${Object.keys(m.logs?.events||{}).length||0}</b><span>Log Events</span></div><div><b>${cmds.length}</b><span>أوامر إدارة</span></div></div><div class="command-grid">${cmds.map(c=>`<article class="command-card"><b>/${esc(c.name)}</b><span>${esc(c.description)}</span><small>${esc(c.category)}</small></article>`).join('')}</div><div class="grid two">${card('⌨','Shortcuts','نفس نظام shortcuts الموجود في البوت',`<p class="muted">${m.shortcuts?.length||0} shortcut</p>${button('إدارة الاختصارات','shortcuts','primary')}`)}${card('!','Warnings','آخر التحذيرات المحفوظة',`<div class="list">${(m.warnings||[]).slice(0,8).map(w=>`<div class="list-row"><span>${esc(w.userId)}</span><strong>${esc(w.reason||'بدون سبب')}</strong></div>`).join('')||'<span class="muted">لا توجد تحذيرات.</span>'}</div>`)}${card('≡','Logs','إعدادات السجلات',`<p class="muted">${m.logs?.globalChannelId?'قناة عامة محددة':'لا توجد قناة عامة'}</p>${button('إدارة السجلات','logs','ghost')}`)}</div>`}
function protection(){const p=state.config?.protection?.protection||{};return sectionHead('SECURITY','الحماية المتقدمة','17 Anti Systems — لكل نظام إعداداته الخاصة، الرتب، القنوات، العقوبة، الحدود والـWhitelist.')+`<div class="security-toolbar">${toggle('secLogs',state.config?.protection?.logsEnabled!==false,'حفظ سجلات الحماية')}<span>${Object.values(p).filter(x=>x?.enabled).length} نظام مفعّل</span>${button('حفظ كل الحماية','save-protection','primary')}</div><div class="protection-grid">${Object.entries(p).map(([k,v])=>protectionCard(k,v)).join('')}</div>`}
function protectionCard(k,v){const roleA=v.allowedRoleIds||[], roleI=v.ignoredRoleIds||[], chI=v.ignoredChannelIds||[];return `<article class="protect-card"><header><div><span class="rule-id">${esc(k)}</span><h3>${esc(labels[k]||k)}</h3></div>${toggle('p_'+k,!!v.enabled,'')}</header><div class="protect-body">${'punishment' in v?`<label class="field"><span>العقوبة</span><select data-prop="punishment"><option value="timeout" ${v.punishment==='timeout'?'selected':''}>Timeout</option><option value="kick" ${v.punishment==='kick'?'selected':''}>Kick</option><option value="ban" ${v.punishment==='ban'?'selected':''}>Ban</option></select></label>`:''}${'limit' in v?input('','الحد',v.limit,'number','data-prop="limit" min="1"'):''}${'windowMs' in v?input('','النافذة بالثواني',(Number(v.windowMs)||1000)/1000,'number','data-prop="windowMs" min="0.1" step="0.1"'):''}${'maxLength' in v?input('','أقصى طول',v.maxLength,'number','data-prop="maxLength" min="1"'):''}${'maxMentions' in v?input('','أقصى Mentions',v.maxMentions,'number','data-prop="maxMentions" min="1"'):''}${'repeatThreshold' in v?input('','عدد التكرار',v.repeatThreshold,'number','data-prop="repeatThreshold" min="2"'):''}${'repeatWindowMs' in v?input('','نافذة التكرار بالثواني',(Number(v.repeatWindowMs)||1000)/1000,'number','data-prop="repeatWindowMs"'):''}${'deleteMessage' in v?toggle('del_'+k,v.deleteMessage!==false,'حذف الرسالة'):''}<label class="field"><span>الرتب المسموحة</span><select multiple data-role-allowed>${resourceOptions('role',roleA,true)}</select></label><label class="field"><span>الرتب المستثناة</span><select multiple data-role-ignored>${resourceOptions('role',roleI,true)}</select></label><label class="field"><span>القنوات المستثناة</span><select multiple data-channel-ignored>${resourceOptions('channel',chI,true)}</select></label>${(k==='antiBot'||k==='antiWebhook'||k==='antiMassJoin')?`<label class="field"><span>Whitelist</span><select multiple data-whitelist>${resourceOptions('member',v.whitelistIds||[],true)}</select></label>`:''}${k==='protectedMembers'?`<label class="field"><span>الأعضاء المحميون</span><select multiple data-protected-members>${resourceOptions('member',v.protectedMemberIds||[],true)}</select></label>`:''}</div></article>`}
function welcome(){const c=state.config?.welcome||{};return sectionHead('WELCOME','نظام الترحيب','تحكم في مكان الترحيب، الرسالة، الرتب، DM، نوع الرسالة وصورة الترحيب.')+`<div class="form-card"><div class="form-grid">${toggle('wEnabled',!!c.enabled,'تفعيل الترحيب')}${toggle('wDM',!!c.welcomeDM,'إرسال الترحيب في DM')}${select('wChannel','channel',c.welcomeChannel||'',false,'قناة الترحيب')}${select('wRole','role',c.autoRole||'',false,'Auto Role للأعضاء')}${select('wBotRole','role',c.botAutoRole||'',false,'Auto Role للبوتات')}<label class="field"><span>نوع الترحيب</span><select id="wType"><option value="message" ${c.welcomeType==='message'?'selected':''}>Message</option><option value="embed" ${c.welcomeType==='embed'?'selected':''}>Embed</option><option value="container" ${c.welcomeType==='container'?'selected':''}>Container</option></select></label>${input('wBg','رابط خلفية الترحيب',c.welcomeImage?.backgroundUrl||'')} ${input('wSize','حجم Avatar',c.welcomeImage?.avatarSize??25,'number','min="8" max="60"')}<label class="field"><span>شكل Avatar</span><select id="wShape"><option value="circle" ${c.welcomeImage?.avatarShape==='circle'?'selected':''}>Circle</option><option value="rounded" ${c.welcomeImage?.avatarShape==='rounded'?'selected':''}>Rounded</option><option value="square" ${c.welcomeImage?.avatarShape==='square'?'selected':''}>Square</option></select></label>${input('wX','Avatar X',c.welcomeImage?.avatarPosition?.x??50,'number','min="0" max="100"')} ${input('wY','Avatar Y',c.welcomeImage?.avatarPosition?.y??50,'number','min="0" max="100"')}</div>${textarea('wMsg','رسالة الترحيب',c.welcomeMessage||'أهلًا [user] في [displayName]!')}<p class="hint">متغيرات Revo: [user] • [displayName] • [server] وغيرها.</p>${button('حفظ الترحيب','save-welcome','primary')}</div>`}
