function tickets(){const list=state.config?.tickets||[];return sectionHead('TICKETS','نظام التذاكر','Panel احترافي: Category، Support Roles، Mention Roles، Forms، Permissions، Claim، Transcript، Logs، Commands.')+`<div class="actions right">${button('إنشاء Ticket Panel','new-ticket','primary')}</div><div class="ticket-grid">${list.map(p=>`<article class="ticket-card"><header><span>${esc(p.emoji||'□')}</span><div><h3>${esc(p.name)}</h3><small>${p.enabled?'مفعّل':'متوقف'} • ${esc(p.openingMethod||'button')}</small></div></header><p>${esc(p.description||'')}</p><div class="chips"><span>Category: ${p.categoryId?'محدد':'—'}</span><span>Support: ${(p.supportRoleIds||[]).length}</span><span>Mention: ${(p.mentionRoleIds||[]).length}</span><span>Form: ${(p.form||[]).length}</span><span>Permissions: ${(p.rolePermissions||[]).length}</span><span>Commands: ${(p.enabledCommands||[]).length}</span></div><div class="actions">${button('تعديل كامل','edit-ticket:'+p._id,'ghost')}${button('حذف','delete-ticket:'+p._id,'danger')}</div></article>`).join('')||'<div class="empty">لا توجد Ticket Panels.</div>'}</div>`}
function levels(){const c=state.config?.level||{};return sectionHead('XP SYSTEM','XP & Levels','كل خيارات XP الموجودة في البوت: limits، cooldown، anti-spam، channels، roles، boosts، rewards، commands.')+`<div class="form-card"><div class="form-grid">${toggle('lEnabled',!!c.enabled,'تفعيل XP')}${toggle('lIgnoreEmpty',c.ignoreEmpty!==false,'تجاهل الرسائل الفارغة')}${toggle('lIgnoreRepeated',c.ignoreRepeated!==false,'تجاهل التكرار')}${toggle('lIgnoreBots',c.ignoreBots!==false,'تجاهل البوتات')}${toggle('lReplace',!!c.roleReplacement,'استبدال رتبة الـReward')}${input('lMaxLevel','Maximum Level',c.maxLevel??100,'number')}${input('lMaxXp','XP لكل Level',c.maxXp??3000,'number')}${input('lXp','XP لكل رسالة',c.xpPerMessage??10,'number')}${input('lCooldown','Cooldown ms',c.cooldownMs??10000,'number')}${input('lMultiplier','Multiplier',c.multiplier??1,'number')}${input('lRepeatWindow','Repeat Window ms',c.repeatWindowMs??30000,'number')}${input('lRepeatThreshold','Repeat Threshold',c.repeatThreshold??3,'number')}${select('lUpChannel','channel',c.levelUpChannelId||'',false,'قناة Level Up')}<label class="field"><span>طريقة رسالة Level Up</span><select id="lUpMode"><option value="same" ${c.levelUpMode==='same'?'selected':''}>نفس القناة</option><option value="channel" ${c.levelUpMode==='channel'?'selected':''}>قناة محددة</option><option value="disabled" ${c.levelUpMode==='disabled'?'selected':''}>بدون رسالة</option></select></label>${select('lXpChannels','channel',c.xpChannelIds||[],true,'قنوات XP المسموحة')}${select('lIgnoredChannels','channel',c.ignoredChannelIds||[],true,'قنوات مستثناة')}${select('lIgnoredRoles','role',c.ignoredRoleIds||[],true,'رتب مستثناة')}</div><div class="subpanel"><h3>XP Boost Roles</h3><div id="boostRows">${(c.boostRoles||[]).map((x,i)=>rowBoost(i,x)).join('')}</div>${button('＋ إضافة Boost','add-boost','ghost')}</div><div class="subpanel"><h3>Level Rewards</h3><div id="rewardRows">${(c.levelRewards||[]).map((x,i)=>rowReward(i,x)).join('')}</div>${button('＋ إضافة Reward','add-reward','ghost')}</div><div class="subpanel"><h3>Registered Level Commands</h3><select id="levelRegistered" multiple>${(state.config?.level?.registeredCommands||[]).map(n=>`<option value="${esc(n)}" selected>/${esc(n)}</option>`).join('')}</select><p class="hint">الأوامر التي يسجلها Revo لنظام XP.</p></div>${button('حفظ XP بالكامل','save-level','primary')}</div>`}
