function responseForm(r){return `<div class="form-card"><div class="form-grid">${input('arTrigger','Trigger',r.trigger||'')}${input('arResponse','Response',r.response||'')}<label class="field"><span>نوع الرد</span><select id="arType"><option value="message" ${r.responseType==='message'||!r.responseType?'selected':''}>message</option><option value="reply" ${r.responseType==='reply'?'selected':''}>reply</option><option value="container" ${r.responseType==='container'?'selected':''}>container</option><option value="embed" ${r.responseType==='embed'?'selected':''}>embed</option></select></label><label class="field"><span>Match</span><select id="arMatch"><option value="exact" ${r.matchMode==='exact'||!r.matchMode?'selected':''}>exact</option><option value="contains" ${r.matchMode==='contains'?'selected':''}>contains</option></select></label>${select('arRoles','role',r.roleIds||[],true,'Roles')}${select('arChannels','channel',r.channelIds||[],true,'Channels')}${toggle('arEnabled',r.enabled!==false,'تفعيل')}${toggle('arDelUser',!!r.deleteUserMessage,'حذف رسالة العضو')}${toggle('arDelBot',!!r.deleteBotResponse,'حذف رد البوت')}${input('arDelay','Delete Delay ms',r.deleteDelay??3000,'number')}${input('arCooldown','Cooldown ms',r.cooldownMs??3000,'number')}</div>${textarea('arText','نص الرد',r.response||'')}<div class="actions">${button('حفظ','save-response','primary')} ${button('إلغاء','close-drawer','ghost')}</div><input type="hidden" id="arId" value="${esc(r.responseId||'')}"></div>`}
function ticketForm(p={}){return `<div class="form-card"><div class="form-grid">${input('tName','اسم الـPanel',p.name||'support')}${input('tEmoji','Emoji',p.emoji||'□')}${input('tColor','Color Hex',p.color?('#'+Number(p.color).toString(16).padStart(6,'0')):'#5865F2')}${input('tImage','Panel Image URL',p.image||'')}${input('tThumb','Panel Thumbnail URL',p.thumbnail||'')}${input('tFormat','Ticket Name Format',p.ticketNameFormat||'ticket-{number}')}${input('tPrefix','Ticket Prefix',p.ticketPrefix||'t!')}${select('tCategory','category',p.categoryId||'',false,'Category')}${select('tSupport','role',p.supportRoleIds||[],true,'Support Roles')}${select('tMention','role',p.mentionRoleIds||[],true,'Mention Roles')}<label class="field"><span>Opening Method</span><select id="tOpen"><option value="button" ${p.openingMethod==='button'||!p.openingMethod?'selected':''}>Button</option><option value="select" ${p.openingMethod==='select'?'selected':''}>Select</option></select></label><label class="field"><span>Message Style</span><select id="tStyle"><option value="embed" ${p.messageStyle==='embed'||!p.messageStyle?'selected':''}>Embed</option><option value="container" ${p.messageStyle==='container'?'selected':''}>Container</option><option value="container-plain" ${p.messageStyle==='container-plain'?'selected':''}>Container Plain</option></select></label>${toggle('tEnabled',p.enabled!==false,'تفعيل')}${toggle('tClaim',p.claimEnabled!==false,'Claim')}${toggle('tTopClaim',!!p.topClaimEnabled,'Topclaim')}${toggle('tTopPoint',!!p.topPointEnabled,'Toppoint')}${toggle('tTranscript',p.transcriptEnabled!==false,'Transcript')}${input('tPoints','Points per Claim',p.claimPoints??0,'number')}${select('tLog','channel',p.logChannelId||'',false,'Log Channel')}${select('tPanelChannel','channel',p.panelChannelId||'',false,'Panel Channel')}${toggle('tQuick',!!p.isQuick,'Quick Panel')}</div>${textarea('tDesc','Panel Description',p.description||'افتح تكت وسيقوم فريق الدعم بمساعدتك.')}<div class="subpanel"><h3>Auto Messages</h3>${textarea('tWelcome','Welcome Message',p.autoMessages?.welcome||'مرحبًا {user}، شكرًا لتواصلك مع فريق الدعم.')}${textarea('tClose','Close Message',p.autoMessages?.close||'تم إغلاق التكت بواسطة {user}.')}</div><div class="subpanel"><h3>Form Questions</h3><div id="ticketQuestions">${(p.form||[]).map(q=>questionRow(q)).join('')}</div>${button('＋ سؤال','add-question','ghost')}</div><div class="subpanel"><h3>Role Permissions</h3><div id="ticketPerms">${(p.rolePermissions||[]).map(x=>permRow(x)).join('')}</div>${button('＋ Role Permission','add-perm','ghost')}</div><div class="subpanel"><h3>Ticket Commands</h3><select id="tCommands" multiple>${(state.catalog?.commands||[]).filter(c=>c.category==='Tickets').map(c=>`<option value="${esc(c.name)}" ${(p.enabledCommands||[]).includes(c.name)?'selected':''}>/${esc(c.name)}</option>`).join('')}</select></div><div class="actions">${button('حفظ Panel','save-ticket','primary')} ${button('إلغاء','close-drawer','ghost')}<input type="hidden" id="tId" value="${esc(p._id||'')}"></div></div>`}
function questionRow(q){return `<div class="repeat-row qrow"><input data-q-label placeholder="Label" value="${esc(q.label||'')}"><input data-q-placeholder placeholder="Placeholder" value="${esc(q.placeholder||'')}"><label><input type="checkbox" data-q-required ${q.required?'checked':''}> مطلوب</label><input type="number" data-q-max value="${q.maxLength||1000}"><button class="icon-btn remove-row">×</button></div>`}
function permRow(x){const p=x.permissions||{};return `<div class="perm-row"><select data-perm-role>${resourceOptions('role',x.roleId)}</select>${['view','send','claim','close','reopen','delete','add','remove','transcript'].map(k=>`<label><input type="checkbox" data-perm="${k}" ${p[k]!==false?'checked':''}>${k}</label>`).join('')}<button class="icon-btn remove-row">×</button></div>`}
function shortcutRow(x={}){const cmds=(state.catalog?.commands||[]).filter(c=>['Administration','Moderation','Voice'].includes(c.category));return `<div class="repeat-row shortcut-row"><input data-s-trigger value="${esc(x.trigger||'')}" placeholder="Trigger"><select data-s-command>${cmds.map(c=>`<option value="${esc(c.name)}" ${x.command===c.name?'selected':''}>/${esc(c.name)} — ${esc(c.description||'')}</option>`).join('')}</select><select multiple data-s-roles>${resourceOptions('role',x.roleIds||[],true)}</select><select data-s-delete-mode><option value="none" ${!x.deleteUserMessage&&!x.deleteBotResponse?'selected':''}>عدم الحذف</option><option value="user" ${x.deleteUserMessage&&!x.deleteBotResponse?'selected':''}>حذف رسالة المستخدم</option><option value="bot" ${!x.deleteUserMessage&&x.deleteBotResponse?'selected':''}>حذف رد البوت</option><option value="both" ${x.deleteUserMessage&&x.deleteBotResponse?'selected':''}>حذف الاثنين</option></select><input type="number" min="0" max="60000" data-s-delay value="${Number.isInteger(x.deleteDelay)?x.deleteDelay:3000}" placeholder="Delete ms"><input type="number" min="0" max="86400000" data-s-cool value="${Number.isInteger(x.cooldownMs)?x.cooldownMs:2000}" placeholder="Cooldown ms"><button class="icon-btn remove-row">×</button></div>`}
function shortcutForm(){const list=state.config?.system?.shortcuts||[];return `<div class="form-card"><h3>اختصارات البوت</h3><p class="hint">نفس نظام Revo: Trigger بدون مسافات + أمر إداري/موديريشن/صوت + رتب مسموحة + وضع الحذف + مدة الحذف + Cooldown.</p><div id="shortcutRows">${list.map(shortcutRow).join('')}</div>${button('＋ إضافة Shortcut','add-shortcut','ghost')} ${button('حفظ الاختصارات','save-shortcuts','primary')}</div>`}
function permissionForm(system){const perms=state.config?.system?.systemSettings?.permissions?.[system]||{};const actions=PERMISSION_ACTIONS[system]||['view','manage'];return `<div class="form-card permission-editor"><div class="permission-note">الصلاحيات هنا خاصة بهذه القائمة. كل إجراء يمكن تحديد الرتب المسموح لها، والمالك/صلاحية Manage Guild تظل قادرة على الإدارة.</div><div id="permissionRows">${actions.map(action=>`<div class="permission-row"><div><b>${esc(PERMISSION_LABELS[action]||action)}</b><small>${esc(action)}</small></div><select multiple data-perm-action="${esc(action)}">${resourceOptions('role',perms[action]||[],true)}</select></div>`).join('')}</div><div class="actions">${button('السماح للجميع','perm-all','ghost')} ${button('حفظ الصلاحيات','save-permissions','primary')}</div></div>`}
function openPermissions(system){openDrawer('صلاحيات • '+(NAV.find(x=>x[0]===system)?.[2]||system),permissionForm(system));$('#drawerBody').dataset.permissionSystem=system;}
function core(){const b=state.config?.botConfig||{};const s=state.config?.system?.systemSettings||{};return sectionHead('REVO CORE','الإعدادات الأساسية','مرجع للقيم الأساسية التي يقرأها البوت من config.js وSystemConfig. القيم الثابتة للعرض حتى لا نغيّر سلوك البوت دون تعديل مصدره.')+`<div class="grid two">${card('◆','Economy Core','القيم الفعلية من config.js',`<div class="metric-row"><b>${fmt(b.dailyReward||0)}</b><span>Daily Reward</span></div><div class="metric-row"><b>${fmt(b.feedbackReward||0)}</b><span>Feedback Reward</span></div><div class="metric-row"><b>${fmt(b.vipReward||0)}</b><span>VIP Reward</span></div><div class="metric-row"><b>${((Number(b.standardTaxRate)||0)*100).toFixed(2)}%</b><span>Standard Tax</span></div><div class="metric-row"><b>${((Number(b.vipTaxRate)||0)*100).toFixed(2)}%</b><span>VIP Tax</span></div><div class="metric-row"><b>${Math.round((Number(b.dailyPeriodMs)||0)/3600000)}h</b><span>Daily Period</span></div>`)}${card('◆','Bot Core','Prefix وAI',`<div class="metric-row"><b>${esc(b.prefix||'—')}</b><span>Prefix</span></div><div class="metric-row"><b>${esc(b.revoPrefix||'—')}</b><span>Revo Prefix</span></div><div class="metric-row"><b>${esc(b.aiModel||'—')}</b><span>AI Model</span></div><div class="metric-row"><b>${b.aiConfigured?'Configured':'Not configured'}</b><span>AI API</span></div>`)}${card('♔','Roles','القيم الثابتة التي يستخدمها Revo',`<div class="metric-row"><code>${esc(b.vipRoleId||'—')}</code><span>VIP Role</span></div><div class="metric-row"><code>${esc(b.premiumRoleId||'—')}</code><span>Premium Role</span></div><div class="metric-row"><code>${esc(b.blacklistRoleId||'—')}</code><span>Blacklist Role</span></div>`)}${card('◈','System Settings','القيم الديناميكية المخزنة للسيرفر',`<pre class="code-block">${esc(JSON.stringify(s,null,2))}</pre>`)}</div>`}function advanced(){const a=state.advanced||{};const c=a.premiumIdentity||{};return sectionHead('ADVANCED / REVO CORE','الأنظمة المتقدمة','كل ما يخص الأعضاء، الملفات الشخصية، الصوت، Feedback، AFK، التذكيرات، هوية البوت وإعدادات التشغيل.')+`<div class="grid two">${card('◆','تخصيص هوية البوت','Avatar / Banner / Nickname مع Premium Identity',`<div class="metric-row"><b>${c.premiumNicknameCustomized?'مخصص':'افتراضي'}</b><span>Nickname</span></div><div class="metric-row"><b>${c.premiumAvatarCustomized?'مخصص':'افتراضي'}</b><span>Avatar</span></div><div class="metric-row"><b>${c.premiumBannerCustomized?'مخصص':'افتراضي'}</b><span>Banner</span></div>${button('إدارة هوية البوت','premium','primary')}`)}${card('□','التحذيرات والموديريشن','Warning records من قاعدة البيانات',`<div class="big-number">${fmt(a.warnings||0)}</div><p class="muted">سجلات تحذيرات محفوظة</p>${button('فتح الإدارة والعقوبات','moderation','ghost')}`)}${card('▧','Profile Backgrounds','خلفيات البروفايل المحفوظة',`<div class="big-number">${fmt(a.profiles||0)}</div><p class="muted">ملفات أعضاء محفوظة</p>${button('فتح Utility','utility','ghost')}`)}${card('◌','Feedback Rewards','طلبات Feedback وحالات المكافآت',`<div class="big-number">${fmt(a.feedback||0)}</div><p class="muted">pending / rewarded / rejected</p>`)}${card('◌','AFK & Reminders','أنظمة AFK والتذكيرات الموجودة في Utility Service',`<div class="stats mini"><div><b>${fmt(a.afk||0)}</b><span>AFK</span></div><div><b>${fmt(a.reminders||0)}</b><span>تذكيرات معلقة</span></div></div>`)}${card('◉','Voice Control','حالة اتصال البوت الصوتية المحفوظة',`<p class="muted">${a.voice?.voiceChannelId?'القناة الصوتية محفوظة':'لا توجد قناة محفوظة'}</p>${a.voice?.voiceChannelId?`<code>${esc(a.voice.voiceChannelId)}</code>`:''}`)}${card('⌘','Command Registry','Slash / Prefix / Come settings',`<p class="muted">${(a.slash?.enabledCommands||[]).length} أمر مفعّل • ${(a.slash?.registeredCommands||[]).length} مسجل</p><div class="metric-row"><b>${a.slash?.comeSlashEnabled?'مفعّل':'معطّل'}</b><span>Come Slash</span></div><div class="metric-row"><b>${a.slash?.comePrefixEnabled?'مفعّل':'معطّل'}</b><span>Come Prefix</span></div>${button('فتح Slash Commands','slash','ghost')}`)}${card('✦','System Core','Shortcuts + System Settings',`<p class="muted">${(a.system?.shortcuts||[]).length} اختصار محفوظ</p>${button('إدارة الاختصارات','shortcuts','primary')}`)}</div>`}

async function reload(){[state.resources,state.config,state.advanced,state.economy,state.moderation,state.utilityData,state.premiumData]=await Promise.all([api(gurl('/api/guild/resources')),api(gurl('/api/guild/full-config')),api(gurl('/api/guild/advanced')),api(gurl('/api/guild/economy')),api(gurl('/api/guild/moderation')),api(gurl('/api/guild/utility')),api(gurl('/api/guild/premium'))]);render();}
document.addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action;if(a.startsWith('open-permissions:')){openPermissions(a.split(':')[1]);return;}if(a==='perm-all'){const system=$('#drawerBody')?.dataset.permissionSystem;for(const s of $$('#permissionRows select[data-perm-action]'))s.innerHTML=resourceOptions('role',[],true);return;}if(a==='save-permissions'){const system=$('#drawerBody')?.dataset.permissionSystem;if(!system)return;const permissions={...(state.config?.system?.systemSettings?.permissions||{})};permissions[system]={};for(const s of $$('#permissionRows select[data-perm-action]'))permissions[system][s.dataset.permAction]=[...s.selectedOptions].map(o=>o.value);await api(gurl('/api/guild/permissions'),{method:'POST',body:JSON.stringify({permissions})});state.config.system=state.config.system||{};state.config.system.systemSettings=state.config.system.systemSettings||{};state.config.system.systemSettings.permissions=permissions;closeDrawer();toast('تم حفظ صلاحيات القائمة بالكامل');return;}});
document.addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(b&&b.closest('#drawer')){const a=b.dataset.action;if(a==='close-drawer'){closeDrawer();return}if(a==='save-response'){const id=val('arId');const body={action:id?'update':'add',responseId:id||undefined,trigger:val('arTrigger'),response:val('arText'),responseType:val('arType'),matchMode:val('arMatch'),roleIds:vals('arRoles'),channelIds:vals('arChannels'),enabled:$('#arEnabled').checked,deleteUserMessage:$('#arDelUser').checked,deleteBotResponse:$('#arDelBot').checked,deleteDelay:+val('arDelay'),cooldownMs:+val('arCooldown')};await api(gurl('/api/guild/autoresponse'),{method:'POST',body:JSON.stringify(body)});closeDrawer();await reload();toast('تم حفظ الرد');return}if(a==='add-question'){$('#ticketQuestions').insertAdjacentHTML('beforeend',questionRow({}));bind();return}if(a==='add-perm'){$('#ticketPerms').insertAdjacentHTML('beforeend',permRow({}));bind();return}if(a==='save-ticket'){const form=[...$$('#ticketQuestions .qrow')].map(r=>({label:r.querySelector('[data-q-label]')?.value||'',placeholder:r.querySelector('[data-q-placeholder]')?.value||'',required:r.querySelector('[data-q-required]')?.checked,maxLength:+(r.querySelector('[data-q-max]')?.value||1000)})).filter(x=>x.label);const rolePermissions=[...$$('#ticketPerms .perm-row')].map(r=>({roleId:r.querySelector('[data-perm-role]')?.value,permissions:Object.fromEntries(['view','send','claim','close','reopen','delete','add','remove','transcript'].map(k=>[k,r.querySelector(`[data-perm="${k}"]`)?.checked!==false]))})).filter(x=>x.roleId);const body={name:val('tName'),description:val('tDesc'),emoji:val('tEmoji'),image:val('tImage')||null,thumbnail:val('tThumb')||null,color:parseInt(val('tColor').replace('#',''),16)||5793266,messageStyle:val('tStyle'),categoryId:val('tCategory')||null,supportRoleIds:vals('tSupport'),mentionRoleIds:vals('tMention'),ticketNameFormat:val('tFormat'),openingMethod:val('tOpen'),form,autoMessages:{welcome:val('tWelcome'),close:val('tClose')},rolePermissions,enabled:$('#tEnabled').checked,isQuick:$('#tQuick').checked,claimEnabled:$('#tClaim').checked,claimPoints:+val('tPoints'),topClaimEnabled:$('#tTopClaim').checked,topPointEnabled:$('#tTopPoint').checked,transcriptEnabled:$('#tTranscript').checked,logChannelId:val('tLog')||null,ticketPrefix:val('tPrefix'),panelChannelId:val('tPanelChannel')||null,enabledCommands:vals('tCommands')};await api(gurl('/api/guild/tickets/panel'),{method:'POST',body:JSON.stringify(body)});closeDrawer();await reload();toast('تم حفظ Ticket Panel بكل إعداداته');return}if(a==='add-shortcut'){$('#shortcutRows').insertAdjacentHTML('beforeend',shortcutRow({}));bind();return}if(a==='save-shortcuts'){const shortcuts=[...$$('#shortcutRows .repeat-row')].map(r=>{const mode=r.querySelector('[data-s-delete-mode]')?.value||'none';return {trigger:r.querySelector('[data-s-trigger]')?.value.trim()||'',command:r.querySelector('[data-s-command]')?.value,roleIds:[...r.querySelector('[data-s-roles]')?.selectedOptions||[]].map(x=>x.value),deleteUserMessage:mode==='user'||mode==='both',deleteBotResponse:mode==='bot'||mode==='both',deleteDelay:+(r.querySelector('[data-s-delay]')?.value||3000),cooldownMs:+(r.querySelector('[data-s-cool]')?.value||2000)};}).filter(x=>x.trigger);await api(gurl('/api/guild/system'),{method:'POST',body:JSON.stringify({shortcuts,logsChannelId:state.config?.system?.logsChannelId||null,systemSettings:state.config?.system?.systemSettings||{}})});closeDrawer();await reload();toast('تم حفظ الاختصارات');return}}
});
